-- =====================================================================
-- 3. PRODUCT CATALOGUE: extra columns, image storage bucket and seed
--    (generated from frontend/src/data/products.js — re-run gen-catalogue to refresh)
-- =====================================================================
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS subcategory TEXT,
  ADD COLUMN IF NOT EXISTS category_slug TEXT,
  ADD COLUMN IF NOT EXISTS subcategory_slug TEXT,
  ADD COLUMN IF NOT EXISTS tagline TEXT,
  ADD COLUMN IF NOT EXISTS sizes TEXT,
  ADD COLUMN IF NOT EXISTS dispatch TEXT,
  ADD COLUMN IF NOT EXISTS applications TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS gallery TEXT[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS sort_order INTEGER DEFAULT 100,
  ADD COLUMN IF NOT EXISTS show_on_home BOOLEAN DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS catalogue_page INTEGER,
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ DEFAULT NOW();

CREATE INDEX IF NOT EXISTS products_sort_idx ON public.products (sort_order, id);
CREATE INDEX IF NOT EXISTS products_category_slug_idx ON public.products (category_slug, subcategory_slug);

-- Public image bucket used by the admin desk uploader (products, categories and machines)
INSERT INTO storage.buckets (id, name, public)
VALUES ('product-images', 'product-images', TRUE)
ON CONFLICT (id) DO UPDATE SET public = TRUE;

DROP POLICY IF EXISTS "Public read product images" ON storage.objects;
DROP POLICY IF EXISTS "Public upload product images" ON storage.objects;
DROP POLICY IF EXISTS "Public update product images" ON storage.objects;
DROP POLICY IF EXISTS "Public delete product images" ON storage.objects;
CREATE POLICY "Public read product images"   ON storage.objects FOR SELECT USING (bucket_id = 'product-images');
CREATE POLICY "Public upload product images" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'product-images');
CREATE POLICY "Public update product images" ON storage.objects FOR UPDATE USING (bucket_id = 'product-images');
CREATE POLICY "Public delete product images" ON storage.objects FOR DELETE USING (bucket_id = 'product-images');

