-- =====================================================================
-- 4. SITE SETTINGS (single row, edited from Admin > Site Settings)
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.site_settings (
    id INTEGER PRIMARY KEY,
    data JSONB NOT NULL DEFAULT '{}'::jsonb,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can access site settings" ON public.site_settings;
CREATE POLICY "Public can access site settings" ON public.site_settings FOR ALL USING (true) WITH CHECK (true);
INSERT INTO public.site_settings (id, data) VALUES (1, '{}'::jsonb) ON CONFLICT (id) DO NOTHING;

-- =====================================================================
-- 5. CATALOGUE HIERARCHY: categories, sub-categories and in-house machines
--    (generated from frontend/src/data/catalogue.js — re-run gen-catalogue to refresh)
-- =====================================================================
CREATE TABLE IF NOT EXISTS public.categories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    company TEXT,
    description TEXT,
    partners TEXT[] DEFAULT '{}',
    capacity TEXT,
    catalogue_page INTEGER,
    image_url TEXT,
    sort_order INTEGER DEFAULT 100,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.subcategories (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_slug TEXT NOT NULL REFERENCES public.categories (slug) ON UPDATE CASCADE ON DELETE CASCADE,
    slug TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    items TEXT[] DEFAULT '{}',
    catalogue_page INTEGER,
    image_url TEXT,
    sort_order INTEGER DEFAULT 100,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (category_slug, slug)
);

CREATE TABLE IF NOT EXISTS public.machines (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug TEXT UNIQUE NOT NULL,
    group_name TEXT NOT NULL,
    name TEXT NOT NULL,
    spec TEXT,
    qty INTEGER,
    stages TEXT[] DEFAULT '{}',
    image_url TEXT,
    catalogue_page INTEGER,
    sort_order INTEGER DEFAULT 100,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

ALTER TABLE public.categories    ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.subcategories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.machines      ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public can access categories"    ON public.categories;
DROP POLICY IF EXISTS "Public can access subcategories" ON public.subcategories;
DROP POLICY IF EXISTS "Public can access machines"      ON public.machines;
CREATE POLICY "Public can access categories"    ON public.categories    FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public can access subcategories" ON public.subcategories FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public can access machines"      ON public.machines      FOR ALL USING (true) WITH CHECK (true);

