-- Products created under the old 5-category admin: map their label onto a catalogue category
UPDATE public.products SET category_slug = CASE
    WHEN category = 'Storage & Warehouse Racking' THEN 'racking'
    WHEN category = 'Mezzanine & Multi-Tier' THEN 'mezzanine'
    WHEN category = 'SS Kitchen & Sheet Metal' THEN 'ss-fabrication'
    WHEN category = 'Heavy Structural & PEB' THEN 'heavy-structural'
    WHEN category = 'Primary Steel Supply' THEN 'steel-supply'
  END
WHERE category_slug IS NULL;
UPDATE public.products p SET category = c.name
  FROM public.categories c WHERE p.category_slug = c.slug AND p.category IS DISTINCT FROM c.name;
UPDATE public.products p SET subcategory_slug = s.slug
  FROM public.subcategories s
  WHERE p.subcategory_slug IS NULL AND s.category_slug = p.category_slug AND lower(s.name) = lower(p.subcategory);

-- 5b. Segment pages: per-item description/image and a category tagline
ALTER TABLE public.subcategories ADD COLUMN IF NOT EXISTS item_details JSONB DEFAULT '{}'::jsonb;
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS tagline TEXT;
